/* Glamours of the Gods (@duwop/gods): an add-on theme pack for websites and brand pages. Strong, godlike
   palettes, each with a dark and a light look, so a site can offer light / dark / system and still decide
   its own colours. Builds on @duwop/theme: the shared rules there turn each theme's --nh / --nc (neutral hue
   and chroma) plus --primary and --glow2 into the full token set, and its effects (Underglow, Shine, Ambient)
   work here unchanged.
   Started 2026-10-10 (builder: "very godlike, strong, and beautiful"). */

/* ---- Palettes. Dark first, then light. ---- */

/* Olympus: white marble and gold. */
.dark[data-theme="olympus"] {
  --nh: 85;
  --nc: 0.01;
  --primary: oklch(0.83 0.13 85);
  --glow2: oklch(0.93 0.035 90);
}
[data-theme="olympus"]:not(.dark) {
  --nh: 85;
  --nc: 0.008;
  --primary: oklch(0.55 0.12 75);
  --glow2: oklch(0.7 0.11 85);
}

/* Apollo: the sun. Radiant gold into sunset amber. */
.dark[data-theme="apollo"] {
  --nh: 55;
  --nc: 0.02;
  --primary: oklch(0.8 0.16 72);
  --glow2: oklch(0.7 0.19 42);
}
[data-theme="apollo"]:not(.dark) {
  --nh: 70;
  --nc: 0.018;
  --primary: oklch(0.56 0.15 58);
  --glow2: oklch(0.66 0.17 40);
}

/* Athena: wisdom. Burnished silver and olive on night blue. */
.dark[data-theme="athena"] {
  --nh: 250;
  --nc: 0.025;
  --primary: oklch(0.87 0.025 245);
  --glow2: oklch(0.74 0.11 125);
}
[data-theme="athena"]:not(.dark) {
  --nh: 240;
  --nc: 0.01;
  --primary: oklch(0.46 0.09 128);
  --glow2: oklch(0.55 0.04 245);
}

/* Poseidon: the deep. Sea glass and pearl over the abyss. */
.dark[data-theme="poseidon"] {
  --nh: 220;
  --nc: 0.045;
  --primary: oklch(0.79 0.12 188);
  --glow2: oklch(0.9 0.035 215);
}
[data-theme="poseidon"]:not(.dark) {
  --nh: 205;
  --nc: 0.015;
  --primary: oklch(0.5 0.1 205);
  --glow2: oklch(0.62 0.09 180);
}

/* Hades: the underworld. Obsidian, pomegranate and ember. */
.dark[data-theme="hades"] {
  --nh: 15;
  --nc: 0.012;
  --primary: oklch(0.68 0.2 22);
  --glow2: oklch(0.74 0.15 55);
}
[data-theme="hades"]:not(.dark) {
  --nh: 25;
  --nc: 0.012;
  --primary: oklch(0.5 0.18 22);
  --glow2: oklch(0.58 0.15 45);
}

/* Ra: lapis lazuli and Egyptian gold. */
.dark[data-theme="ra"] {
  --nh: 265;
  --nc: 0.06;
  --primary: oklch(0.83 0.15 85);
  --glow2: oklch(0.62 0.17 262);
}
[data-theme="ra"]:not(.dark) {
  --nh: 255;
  --nc: 0.014;
  --primary: oklch(0.48 0.15 262);
  --glow2: oklch(0.68 0.13 80);
}

/* ---- The divine look, shared by every god. ---- */
:is([data-theme="olympus"], [data-theme="apollo"], [data-theme="athena"], [data-theme="poseidon"], [data-theme="hades"], [data-theme="ra"]) {
  --god: 1;
  --app-display: "Cinzel", "Trajan Pro", serif;
  --radius: 0.5rem;
  /* Gilt ends stay close to the main colour so every part of a title stays readable (checked 2026-10-10). */
  --gilt: linear-gradient(180deg, color-mix(in oklch, var(--primary) 55%, white) 0%, var(--primary) 48%, color-mix(in oklch, var(--primary) 85%, black) 100%);
}

/* On light pages the gilt runs darker, so titles stay readable on marble. */
:is([data-theme="olympus"], [data-theme="apollo"], [data-theme="athena"], [data-theme="poseidon"], [data-theme="hades"], [data-theme="ra"]):not(.dark) {
  --gilt: linear-gradient(180deg, color-mix(in oklch, var(--primary) 90%, white) 0%, var(--primary) 45%, color-mix(in oklch, var(--primary) 60%, black) 100%);
}

/* Titles carved in gold: Roman inscription capitals, a gilded fill, a soft halo in the dark. */
:is([data-theme="olympus"], [data-theme="apollo"], [data-theme="athena"], [data-theme="poseidon"], [data-theme="hades"], [data-theme="ra"]) .fx-title {
  font-family: var(--app-display);
  font-size-adjust: none;
  font-weight: 600;
  letter-spacing: 0.06em;
}
:is([data-theme="olympus"], [data-theme="apollo"], [data-theme="athena"], [data-theme="poseidon"], [data-theme="hades"], [data-theme="ra"]):not([data-fx~="neon"]) .fx-title,
.dark:is([data-theme="olympus"], [data-theme="apollo"], [data-theme="athena"], [data-theme="poseidon"], [data-theme="hades"], [data-theme="ra"]):not([data-theme="mono"]):not([data-fx~="neon"]) .fx-title {
  background: var(--gilt);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  /* Each line gets the whole gilt, so a two-line title doesn't go pale on top and dark below. */
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}
.dark:is([data-theme="olympus"], [data-theme="apollo"], [data-theme="athena"], [data-theme="poseidon"], [data-theme="hades"], [data-theme="ra"]):not([data-fx~="neon"]) .fx-title {
  filter: drop-shadow(0 0 18px color-mix(in oklch, var(--primary) 30%, transparent));
}

/* Cards: a hairline of the god's colour and a gilded crown along the top edge. */
:is([data-theme="olympus"], [data-theme="apollo"], [data-theme="athena"], [data-theme="poseidon"], [data-theme="hades"], [data-theme="ra"]) [data-slot="card"] {
  position: relative;
  border-color: color-mix(in oklch, var(--primary) 28%, var(--border));
}
:is([data-theme="olympus"], [data-theme="apollo"], [data-theme="athena"], [data-theme="poseidon"], [data-theme="hades"], [data-theme="ra"]) [data-slot="card"]::before {
  content: "";
  position: absolute;
  inset: -1px 18% auto;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--primary), transparent);
  pointer-events: none;
}

/* Main buttons: struck from gold, with a lit top edge. */
:is([data-theme="olympus"], [data-theme="apollo"], [data-theme="athena"], [data-theme="poseidon"], [data-theme="hades"], [data-theme="ra"]) [data-slot="button"][data-variant="default"] {
  background: var(--gilt);
  box-shadow: inset 0 1px 0 color-mix(in oklch, white 45%, transparent), 0 6px 20px -10px var(--primary);
  letter-spacing: 0.04em;
}

/* Eyebrows and small caps labels: a laurel of spacing. */
:is([data-theme="olympus"], [data-theme="apollo"], [data-theme="athena"], [data-theme="poseidon"], [data-theme="hades"], [data-theme="ra"]) .fx-eyebrow {
  font-family: var(--app-display);
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--primary);
}

/* A divider worthy of a temple: a line with a diamond at its heart. */
.fx-divider {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--primary);
}
.fx-divider::before,
.fx-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, transparent, color-mix(in oklch, var(--primary) 60%, transparent));
}
.fx-divider::after {
  transform: scaleX(-1);
}

// Glamours of the Gods (@duwop/gods): the theme entries for gods.css. Each has a light and a dark look
// (dark: "both"), so a site can offer light / dark / system (@duwop/mode) and still choose its own colours.
// Add them in lib/duwop-config.ts: import { gods } from "./gods"; ... extraThemes: gods.

import type { Theme } from "./theme";

const god = (id: string, name: string, note: string): Theme => ({
  id,
  name,
  note,
  dark: "both",
  display: "Cinzel",
  effects: ["underglow", "ambient"],
});

export const gods: Theme[] = [
  god("olympus", "Olympus", "White marble and gold."),
  god("apollo", "Apollo", "The sun: radiant gold into sunset amber."),
  god("athena", "Athena", "Burnished silver and olive."),
  god("poseidon", "Poseidon", "Sea glass and pearl over the deep."),
  god("hades", "Hades", "Obsidian, pomegranate and ember."),
  god("ra", "Ra", "Lapis lazuli and Egyptian gold."),
];
